window.NVC = window.NVC || {};

(window.NVC.scenarios = window.NVC.scenarios || []).push(
{ id:"health", name:"Healthcare & Caregiving", icon:"🩺", hue:190, blurb:"Speak up for yourself and others in clinics, hospitals and care at home — where fear, fatigue and power gaps run high.", cases:[
{ id:"health-01", title:"Rushed GP appointment", context:"Dr. Okafor starts typing a prescription two minutes into Leila’s appointment, before she has mentioned her second symptom.", who:"adult", level:1,
  jackal:"You’re not even listening — you doctors just want us out the door.",
  giraffe:{ o:"I’ve mentioned one of the two things I came in about, and I see you’re writing a prescription.", f:"I’m feeling a bit anxious", n:"because I need to be fully heard about my health.", r:"Would you be willing to give me two minutes to describe the other symptom before we decide on treatment?" },
  say:"Before you finish that, I’m a bit anxious because there’s a second thing I haven’t mentioned yet. Could I take two minutes to describe it so we can decide together?",
  empathy:"Are you feeling stretched because you’re running behind and want to give every patient enough care today?",
  tip:"Write your top two concerns on a note before the appointment and name them both in your first sentence." },
{ id:"health-02", title:"Nurse slow to answer bell", context:"Arjun’s father pressed the call bell 25 minutes ago for help to the toilet. When nurse Bridget arrives she looks exhausted.", who:"adult", level:2,
  jackal:"Finally! Do you have any idea how long he’s been waiting? This place is a disgrace.",
  giraffe:{ o:"Dad pressed the bell about 25 minutes ago and needed the toilet.", f:"I felt scared and helpless", n:"because I want him to have dignity and safety.", r:"Could you tell me what the best way is to get help quickly when it’s urgent like this?" },
  say:"I can see you’re run off your feet. Dad pressed the bell about 25 minutes ago for the toilet and I felt really helpless watching him wait. What’s the best way for us to get help quickly when it’s urgent?",
  empathy:"Are you feeling overwhelmed because there are more patients than hands tonight and you want to care for each of them properly?",
  tip:"Lead with one sentence acknowledging the staff member’s load — it lowers defensiveness and speeds up help." },
{ id:"health-03", title:"Teen refuses medication", context:"Sixteen-year-old Mateo, recently diagnosed with type 1 diabetes, has skipped his evening insulin twice this week.", who:"teen", level:3,
  jackal:"Do you want to end up in hospital? You’re being completely irresponsible!",
  giraffe:{ o:"I noticed your evening insulin wasn’t taken on Monday or Wednesday.", f:"I’m really worried", n:"because your safety matters so much to me, and I also want you to have a say in how this goes.", r:"Would you be willing to talk with me tonight about what makes the evening dose hard?" },
  say:"I saw the evening insulin got missed Monday and Wednesday, and I’m worried — and I also don’t want to just nag you. Could we talk tonight about what makes that dose hard?",
  empathy:"Are you feeling fed up because you want your life to feel normal and to be in charge of your own body?",
  tip:"With teens and chronic illness, ask about the obstacle (Ross Greene’s ‘lagging skills’ lens) before proposing any plan." },
{ id:"health-04", title:"Anxious relative at reception", context:"You work hospital reception. Mr. Nakamura demands to see his wife in surgery right now and is raising his voice.", who:"adult", level:2,
  jackal:"Sir, you need to calm down or I’ll call security.",
  giraffe:{ o:"You’ve asked three times to see your wife, and she’s still in theatre.", f:"I imagine you’re terrified", n:"and need to know she’s safe.", r:"Would it help if I phone the theatre desk now and ask when the surgeon can update you?" },
  say:"You’ve asked a few times and I can hear how frightened you are — you just want to know she’s okay. Let me phone the theatre desk right now and ask when the surgeon can come and update you. Would that help?",
  empathy:"Are you scared and desperate for information because you love her and can’t bear not knowing?",
  tip:"When someone is in survival state, give empathy plus one concrete action before any rules." },
{ id:"health-05", title:"Doctor dismisses pain", context:"Amara has had pelvic pain for months; the specialist says it’s ‘probably stress’ and closes the file.", who:"adult", level:3,
  jackal:"So it’s all in my head? This is exactly why women don’t get diagnosed.",
  giraffe:{ o:"You said the pain is probably stress, and no further tests have been mentioned.", f:"I feel frustrated and discouraged", n:"because I need my experience taken seriously and a clear path forward.", r:"Would you be willing to note in my file that I requested further investigation, and tell me what the next step would be if stress isn’t the cause?" },
  say:"I hear that stress may play a part. I’m discouraged though, because this pain has been going on for months and I need a clear path forward. Could you note in my file that I asked for further tests, and tell me what we’d do next if it isn’t stress?",
  empathy:"Are you feeling cautious because you want to avoid unnecessary tests and protect me from harm?",
  tip:"Asking for your request to be documented is calm, legitimate and often shifts the conversation." },
{ id:"health-06", title:"Sibling not sharing care", context:"Priya visits their mother with MS four times a week; her brother Rohan visits once a month and gives advice by text.", who:"peer", level:2,
  jackal:"Easy for you to give orders from your sofa. You’ve basically abandoned Mum.",
  giraffe:{ o:"This month I’ve visited Mum about sixteen times and you’ve visited once.", f:"I’m exhausted and resentful", n:"because I need support and fairness in caring for her.", r:"Would you be willing to take every Saturday afternoon starting this week?" },
  say:"Rohan, I’ve been to Mum’s about sixteen times this month and I’m running on empty. I need us to share this more fairly. Could you take Saturday afternoons, starting this week?",
  empathy:"Are you feeling guilty or unsure how to help because seeing Mum like this is painful for you too?",
  tip:"Replace ‘you should help more’ with one specific, recurring slot — vague asks get vague answers." },
{ id:"health-07", title:"Partner with depression", context:"Jonas’s wife Elin has stayed in bed most of the weekend and hasn’t answered her sister’s calls.", who:"adult", level:2,
  jackal:"Just get up and do something. Lying there all day is making it worse.",
  giraffe:{ o:"You’ve spent most of Saturday and Sunday in bed and haven’t picked up Karin’s calls.", f:"I’m worried and feel a bit lost", n:"because I care about you and want to understand how to support you.", r:"Would you tell me one small thing that would feel good to you right now — even just sitting together?" },
  say:"Love, I notice you’ve been in bed most of the weekend and I’m worried — I don’t want to push, I just want to understand. Is there one small thing that would feel okay right now? Even sitting together?",
  empathy:"Are you feeling heavy and drained, and needing gentleness rather than pressure?",
  tip:"With depression, offer tiny options instead of advice; presence counts more than solutions." },
{ id:"health-08", title:"Colleague’s hand hygiene", context:"Nurse Kwame sees a junior colleague, Sofie, move between two patients without washing her hands.", who:"peer", level:2,
  jackal:"Are you trying to spread infection? That’s basic stuff!",
  giraffe:{ o:"I saw you go from bed 4 to bed 5 without washing or gelling your hands.", f:"I felt uneasy", n:"because patient safety is really important to me — and I know how busy it gets.", r:"Would you be okay gelling now before you start with bed 5?" },
  say:"Hey Sofie, quick one — I saw you go from bed 4 to bed 5 without gelling. I know it’s chaos today; I’m just uneasy about infection. Would you mind gelling before you start here?",
  empathy:"Are you feeling rushed because you’re trying to keep up with everything at once?",
  tip:"Raise safety issues immediately, privately and briefly — the shorter the message, the less shame." },
{ id:"health-09", title:"Wheelchair user talked over", context:"At a hospital appointment, the consultant directs all questions to Dani’s partner instead of to Dani, who uses a wheelchair.", who:"adult", level:2,
  jackal:"I’m right here! I’m disabled, not invisible.",
  giraffe:{ o:"The last four questions were asked to Tom rather than to me.", f:"I feel frustrated", n:"because I need respect and to be part of decisions about my own care.", r:"Would you be willing to speak directly to me from here on?" },
  say:"I notice the last few questions went to Tom rather than me. I’d really like to be part of decisions about my own care — could you speak to me directly from here on?",
  empathy:"Are you trying to be efficient and perhaps unsure who to address?",
  tip:"Name the pattern factually (‘the last four questions’) rather than the person’s character." },
{ id:"health-10", title:"Elderly patient refuses wash", context:"Care worker Fatima arrives to help 84-year-old Mr. Hughes shower; he shouts that he doesn’t need a ‘babysitter’.", who:"older", level:2,
  jackal:"Well, you can’t stay dirty, so let’s just get it done.",
  giraffe:{ o:"You’ve said you don’t want help showering today.", f:"I’m guessing you feel annoyed", n:"and want to keep your independence and privacy.", r:"Would you like to wash yourself while I just wait outside the door in case you need anything?" },
  say:"Sounds like you’d much rather do this on your own — that makes complete sense. How about you wash yourself, and I’ll wait just outside the door in case you need a hand?",
  empathy:"Are you feeling embarrassed and wanting to be treated as the capable man you are?",
  tip:"Offer choices that preserve autonomy; most ‘refusals’ are about dignity, not hygiene." },
{ id:"health-11", title:"Friend’s suicidal comment", context:"Over coffee, your friend Yusuf says quietly, ‘Sometimes I think everyone would be better off without me.’", who:"peer", level:3,
  jackal:"Don’t say that! You have so much to live for.",
  giraffe:{ o:"You just said everyone might be better off without you.", f:"I feel scared and I really care", n:"because your life matters to me and I want to understand what you’re going through.", r:"Are you having thoughts of ending your life — and would you be willing to call a helpline or doctor with me today?" },
  say:"Yusuf, what you just said matters to me, and I want to ask directly: are you thinking about ending your life? I’m here, I’m not going anywhere, and I’d like us to call a doctor or helpline together today.",
  empathy:"Are you feeling exhausted and hopeless, needing someone to really see how much pain you’re carrying?",
  tip:"Asking directly about suicide does not plant the idea; it opens the door. Stay with them and connect them to professional help." },
{ id:"health-12", title:"Pharmacy wrong dose", context:"Ms. Abara notices her mother’s new tablets are 50mg, not the 25mg the doctor prescribed.", who:"adult", level:1,
  jackal:"You could have killed her! Don’t you people check anything?",
  giraffe:{ o:"The box says 50mg, and the prescription says 25mg.", f:"I’m alarmed", n:"because I need to be sure Mum’s medication is safe.", r:"Could you check this with me now and replace it if it’s wrong?" },
  say:"I’m quite alarmed — the box says 50mg but the prescription says 25mg. Could you check it with me now and swap it if it’s wrong?",
  empathy:"Are you feeling concerned too, and wanting to put it right quickly?",
  tip:"Bring the paperwork; let facts carry the urgency so your tone doesn’t have to." },
{ id:"health-13", title:"Child scared of injection", context:"Seven-year-old Zara clings to her dad and screams as the nurse prepares a vaccine.", who:"child", level:1,
  jackal:"Stop being a baby — it’s just a tiny scratch.",
  giraffe:{ o:"You’re holding onto me tight and screaming.", f:"You seem really scared", n:"and you need to feel safe.", r:"Would you like to squeeze my hand as hard as you can and breathe out like blowing a candle while she does it?" },
  say:"You’re holding on so tight — you’re really scared, aren’t you? That’s okay. Squeeze my hand as hard as you want and let’s blow out a big pretend candle together.",
  empathy:"Are you scared because it might hurt and you want someone to keep you safe?",
  tip:"Name the feeling first, then give her body a job — squeezing a hand or slow out-breaths help a scared child feel some control." },
{ id:"health-14", title:"Patient yelling at nurse", context:"Nurse Marisol is told by a patient, Mr. Kowalski, that she is ‘useless’ when his pain relief is delayed.", who:"adult", level:3,
  jackal:"I’m doing my best — there’s no need to be so rude.",
  giraffe:{ o:"You’re still in pain and the medication is 20 minutes late.", f:"You sound really frustrated and uncomfortable", n:"and need relief and to know someone is on it.", r:"Would it help if I tell you exactly when I’ll be back with it — in ten minutes?" },
  say:"You’re still in pain and it’s twenty minutes late — no wonder you’re frustrated. I’m getting it signed off now and I’ll be back within ten minutes. Is there anything that would make you more comfortable meanwhile?",
  empathy:"Are you in pain and scared, needing reassurance that you haven’t been forgotten?",
  tip:"Empathy isn’t agreement; you can hear the need under insults and still set limits later if they continue." },
{ id:"health-15", title:"Partner skips therapy", context:"Lucas has cancelled his last three counselling sessions; his partner Ade booked them together after a hard year.", who:"adult", level:2,
  jackal:"You obviously don’t care about fixing anything.",
  giraffe:{ o:"The last three counselling sessions were cancelled.", f:"I feel sad and worried", n:"because I want us to keep growing and I need to trust we’re both in this.", r:"Would you be willing to tell me what’s getting in the way?" },
  say:"I noticed the last three sessions got cancelled, and I feel sad — I really want us to keep working at this. Can you tell me what’s getting in the way for you?",
  empathy:"Are you finding the sessions uncomfortable and needing more safety or a different approach?",
  tip:"Ask about the barrier before re-committing to the strategy; the need may be met another way." },
{ id:"health-16", title:"Carer burnout with spouse", context:"Ingrid has cared for her husband after his stroke for two years. Tonight he complains the dinner is cold.", who:"adult", level:3,
  jackal:"Then make it yourself! I do everything and get nothing but complaints.",
  giraffe:{ o:"You said the dinner is cold.", f:"I’m feeling worn out and hurt", n:"because I need appreciation and some rest too.", r:"Would you be willing to tell me one thing you appreciated today, and can we talk tomorrow about getting respite help?" },
  say:"When I hear the dinner is cold, I feel hurt — I’m so tired and I need to know what I do matters. Could you tell me one thing you appreciated today? And tomorrow I’d like to talk about getting some respite help.",
  empathy:"Are you feeling frustrated and powerless because you miss doing things for yourself?",
  tip:"Caregivers need empathy too — book respite before you hit empty, not after." },
{ id:"health-17", title:"Psychiatric ward visit", context:"Hamid visits his sister Noor on a mental health ward. She accuses him of ‘locking her up’.", who:"adult", level:3,
  jackal:"Nobody locked you up — you did this to yourself.",
  giraffe:{ o:"You said I locked you up.", f:"It sounds like you feel angry and trapped", n:"and need freedom and to be trusted.", r:"Would you tell me what feels hardest about being here?" },
  say:"You feel like I locked you up — that sounds so frustrating and scary. I want to understand. What’s the hardest part of being here for you?",
  empathy:"Are you feeling powerless and wanting your choices respected?",
  tip:"Xavier Amador’s LEAP approach: Listen, Empathize, Agree where you can, Partner — don’t argue about the illness." },
{ id:"health-18", title:"Receptionist refuses appointment", context:"The surgery receptionist tells Mrs. Delgado there are no appointments for two weeks; her toddler has had a fever for three days.", who:"adult", level:2,
  jackal:"That’s ridiculous — my child could be seriously ill!",
  giraffe:{ o:"My son has had a fever for three days and the next appointment is in two weeks.", f:"I’m worried", n:"because I need reassurance he’s safe.", r:"Could you ask a doctor or nurse to call me back today to assess him?" },
  say:"I understand you’re fully booked. My son’s had a fever for three days and I’m worried. Could a doctor or nurse call me back today to assess whether he needs to be seen?",
  empathy:"Are you feeling pressured because you have to turn people away all day?",
  tip:"Ask for the triage route rather than fighting the booking system." },
{ id:"health-19", title:"Doctor jargon overload", context:"After surgery, the consultant explains ‘anastomotic leak risk’ and leaves before Mrs. Chen understands.", who:"older", level:1,
  jackal:"I didn’t understand a word — you could at least speak English.",
  giraffe:{ o:"I heard several terms I don’t recognise, like ‘anastomotic leak’.", f:"I feel confused and nervous", n:"because I need to understand what’s happening to my body.", r:"Could you explain it in plain words and tell me what signs to watch for?" },
  say:"Sorry, I’m a bit lost and nervous — I didn’t understand ‘anastomotic leak’. Could you explain it in plain words and tell me what signs I should watch for?",
  empathy:"Are you busy and wanting to give accurate information quickly?",
  tip:"Try ‘teach-back’: repeat in your own words what you heard and ask if you got it right." },
{ id:"health-20", title:"Autistic adult in ER", context:"In a loud emergency room, Theo, an autistic adult, covers his ears and won’t answer the triage nurse.", who:"adult", level:2,
  jackal:"Sir, I need you to answer my questions now.",
  giraffe:{ o:"You’re covering your ears and it’s very loud in here.", f:"I imagine this feels overwhelming", n:"and you need quiet and predictability.", r:"Would it help to move to the side room and answer by writing or typing?" },
  say:"It’s really loud here and I can see you’re covering your ears — that must be a lot. Would it help to move to the quieter side room, and you can type or write your answers if that’s easier?",
  empathy:"Are you overloaded and needing calm before you can talk?",
  tip:"Reduce sensory input and offer alternative communication before repeating questions." },
{ id:"health-21", title:"Family disagree on treatment", context:"The Mensah siblings argue in the hospital corridor about whether their father should start another round of chemo.", who:"group", level:3,
  jackal:"You just want to give up on him!",
  giraffe:{ o:"We’ve each said different things about the next round of chemo.", f:"I feel torn and scared", n:"because I want Dad’s wishes respected and our family to stay connected.", r:"Would you all be willing to meet with the palliative team together and hear what Dad wants first?" },
  say:"I can hear we all want what’s best for Dad and we see it differently. I’m scared and torn. Could we meet with the palliative team together, and start by hearing what Dad himself wants?",
  empathy:"Are you each frightened of losing him and needing to feel you did right by him?",
  tip:"Shift the focus to the patient’s own values; it unites siblings who are arguing strategies." },
{ id:"health-22", title:"Boss doubts sick leave", context:"After a migraine day, Seo-yeon’s manager says, ‘Funny how these always fall on a Monday.’", who:"adult", level:2,
  jackal:"Are you calling me a liar?",
  giraffe:{ o:"You mentioned my sick days have fallen on Mondays.", f:"I feel hurt and uneasy", n:"because I need trust and understanding about a real health condition.", r:"Would you be open to me sharing my migraine plan and a doctor’s note so we can agree how to handle it?" },
  say:"When you said they always fall on Mondays, I felt uneasy — my migraines are real and I’d like us to trust each other. Could I share my doctor’s note and migraine plan, so we can agree how to handle flare-ups?",
  empathy:"Are you worried about team cover and needing predictability?",
  tip:"Turn suspicion into a shared plan; it addresses the manager’s need for reliability." }
]},
{ id:"elders", name:"Ageing Parents & Elders", icon:"🧓", hue:30, blurb:"Navigate role reversals with ageing parents and elders while honouring both their dignity and your own limits.", cases:[
{ id:"elders-01", title:"The same story again", context:"Grandpa Ibrahim starts telling, for the fourth time this week, the story of his first job at the docks.", who:"older", level:1,
  jackal:"You’ve told us that a hundred times, Grandpa.",
  giraffe:{ o:"You’re telling the story about your first job at the docks.", f:"I feel warm hearing how proud you were", n:"and I value connection with you.", r:"Would you tell me what your boss there was like? I don’t think I’ve heard that part." },
  say:"The docks story! You sound so proud of that time. What was your boss there like? I don’t think I know that part.",
  empathy:"Are you wanting to feel that your life and work mattered and are remembered?",
  tip:"Ask a new question about an old story — it turns repetition into connection." },
{ id:"elders-02", title:"Taking the car keys", context:"Linh’s 82-year-old mother has scraped the car twice this month and got lost driving to the market.", who:"older", level:3,
  jackal:"You’re a danger on the road, Mum. You have to stop driving.",
  giraffe:{ o:"The car has two new scrapes this month, and last Tuesday you got lost on the way to the market.", f:"I’m scared", n:"because I care about your safety and others’, and I know how much your independence means to you.", r:"Would you be willing to do a driving assessment with an instructor so we can decide together?" },
  say:"Mum, I know how much driving means to you — it’s your freedom. With the two scrapes and getting lost on Tuesday, I’m scared. Would you do a driving assessment with an instructor, so we decide based on that rather than me nagging?",
  empathy:"Are you afraid of losing your freedom and being dependent on others?",
  tip:"Use a neutral third party (assessment, doctor) and plan alternative transport before the conversation." },
{ id:"elders-03", title:"Dementia accusation of theft", context:"Esperanza’s father, who has dementia, insists she stole his wallet. It’s in his coat pocket.", who:"older", level:3,
  jackal:"I didn’t steal anything! It’s in your coat, like always.",
  giraffe:{ o:"You can’t find your wallet.", f:"You seem worried and upset", n:"and need to feel your things are safe.", r:"Shall we look together in your coat and drawer?" },
  say:"Oh no, you can’t find your wallet — that’s really worrying. Let’s look together. Shall we start with your coat?",
  empathy:"Are you feeling anxious and needing security when things keep going missing?",
  tip:"With dementia, don’t argue the facts — meet the feeling and redirect (validation approach)." },
{ id:"elders-04", title:"Moving into care", context:"After a fall, the doctors recommend residential care for Mr. Ferreira. He says, ‘You’re just dumping me.’", who:"older", level:3,
  jackal:"We’re not dumping you — we can’t look after you anymore!",
  giraffe:{ o:"You said you feel we’re dumping you.", f:"I hear how hurt and scared you are", n:"and how much you need to belong and be wanted.", r:"Would you come and visit two places with me this week, and tell me what matters most to you in a new home?" },
  say:"Pai, when you say we’re dumping you, I hear how scared and hurt you are. We want you close and safe. Would you visit two places with me this week and tell me what matters most to you?",
  empathy:"Are you grieving the loss of your home and fearing you won’t matter anymore?",
  tip:"Give real choices within the decision; involvement reduces the sense of abandonment." },
{ id:"elders-05", title:"Refusing hearing aids", context:"Mrs. Adeyemi keeps asking everyone to repeat themselves but leaves her hearing aids in the drawer.", who:"older", level:2,
  jackal:"If you wore your hearing aids we wouldn’t have to shout.",
  giraffe:{ o:"Your hearing aids have been in the drawer this week, and you’ve asked us to repeat things a lot at dinner.", f:"I feel sad", n:"because I want you to be part of our conversations.", r:"Would you tell me what you don’t like about them?" },
  say:"I’ve noticed your hearing aids are in the drawer and dinner’s been hard to follow for you. I miss having you in the conversation. What is it you don’t like about them?",
  empathy:"Are they uncomfortable or do they make you feel old, and you need comfort or dignity?",
  tip:"Ask about the obstacle (fit, noise, stigma); solutions often follow." },
{ id:"elders-06", title:"Grandparent overrides rules", context:"Every visit, Oma gives Leon (5) sweets right before dinner even though his parents have asked her not to.", who:"older", level:2,
  jackal:"You never respect our rules — you think you know better.",
  giraffe:{ o:"Leon had sweets just before dinner today, after we talked about it last week.", f:"I feel frustrated", n:"because I need consistency for him, and I also love how generous you are with him.", r:"Would you be willing to give him treats after dinner instead?" },
  say:"Oma, I love how much you spoil him. I felt frustrated today though, since he had sweets right before dinner again. Would you be willing to save treats for after dinner?",
  empathy:"Are you wanting to show love and have special moments with him?",
  tip:"Offer the grandparent a ‘yes’ alternative that still meets their need to delight the child." },
{ id:"elders-07", title:"Lonely parent calls daily", context:"Kenji’s widowed mother calls him three times a day at work and is hurt when he doesn’t answer.", who:"older", level:2,
  jackal:"Mum, I can’t talk all the time — I have a job!",
  giraffe:{ o:"You’ve called me three times today while I was at work.", f:"I feel torn", n:"because I need focus at work and I also want you to feel connected.", r:"Would you be willing to have a set call every evening at 7 instead?" },
  say:"Mum, I love hearing from you and I can’t pick up at work — I feel torn when I miss your calls. How about we have a proper chat every evening at 7?",
  empathy:"Are you feeling lonely since Dad died and needing company and reassurance?",
  tip:"A predictable ritual meets the need for connection better than ad-hoc calls." },
{ id:"elders-08", title:"Inheritance tension", context:"At the family meal, Arash’s sister says she should get the house because she ‘did all the caring’.", who:"peer", level:3,
  jackal:"So now it’s about money? Typical.",
  giraffe:{ o:"You said you should get the house because you did most of the caring.", f:"I feel uncomfortable and a bit defensive", n:"and I also want to honour what you gave and keep fairness between us.", r:"Would you be willing to discuss it with a mediator after the will is read, rather than at dinner?" },
  say:"I hear you saying you carried most of the caring, and you did give a lot. I’m uncomfortable deciding this over dinner. Could we sit down with a mediator once the will is read?",
  empathy:"Are you feeling unrecognised for years of sacrifice and needing acknowledgement?",
  tip:"Acknowledge contributions separately from dividing assets — often the need is recognition." },
{ id:"elders-09", title:"Parent won’t accept help", context:"Olu’s father insists on cleaning gutters on a ladder at 79, despite a recent dizzy spell.", who:"older", level:2,
  jackal:"Are you crazy? You’ll break your neck!",
  giraffe:{ o:"You’re up on the ladder, and last week you had a dizzy spell.", f:"I feel scared", n:"because I care about your safety and also know you like doing things yourself.", r:"Would you hold the ladder and direct me while I do the top bit?" },
  say:"Dad, you had that dizzy spell last week and seeing you up there scares me. How about you hold the ladder and tell me what to do while I go up?",
  empathy:"Are you wanting to feel capable and useful?",
  tip:"Give the elder an expert or supervising role — it protects safety and pride." },
{ id:"elders-10", title:"Elder’s prejudiced comment", context:"At a family gathering, Uncle Dieter makes a derogatory joke about immigrants while grandchildren listen.", who:"older", level:3,
  jackal:"That’s racist. You’re embarrassing everyone.",
  giraffe:{ o:"You just made a joke about immigrants in front of the kids.", f:"I feel uncomfortable", n:"because respect and kindness for everyone matter a lot to me.", r:"Would you be willing to keep jokes like that out of family dinners?" },
  say:"Uncle Dieter, I’m uncomfortable with that joke, especially with the kids here — respect for everyone really matters to me. Can we keep that kind of joke out of family dinners?",
  empathy:"Are you feeling worried about changes in the country and needing to feel heard?",
  tip:"State your value and a clear request; you can explore their underlying fears later in private." },
{ id:"elders-11", title:"Sundowning anxiety", context:"Every evening, Mrs. Yilmaz, who has dementia, insists she must go home to feed her children, now in their 50s.", who:"older", level:2,
  jackal:"Your children are grown up, Mum. We’ve been through this.",
  giraffe:{ o:"You’re saying you need to go home to feed the children.", f:"You sound worried", n:"and you care so much about them being looked after.", r:"Would you tell me what you used to cook for them?" },
  say:"You’re worried about feeding the children — you’ve always looked after everyone. What did you used to cook for them?",
  empathy:"Are you needing to feel useful and that your loved ones are safe?",
  tip:"Join their reality and redirect to memory or activity; correcting usually escalates distress." },
{ id:"elders-12", title:"Parent criticises your parenting", context:"Rafael’s mother says in front of his kids, ‘In my day children didn’t talk back like that.’", who:"older", level:2,
  jackal:"Times have changed, Mum. Stop undermining me.",
  giraffe:{ o:"You said children didn’t talk back in your day, in front of the kids.", f:"I feel tense", n:"because I need support in how I parent and a united front for the children.", r:"Would you share concerns with me privately instead of in front of them?" },
  say:"Mum, when comments like that happen in front of the kids I feel tense — I need us to be on the same team. Could you tell me privately when something bothers you?",
  empathy:"Are you worried about the kids and wanting your experience to count?",
  tip:"Invite their wisdom privately; it meets their need to contribute without undermining you." },
{ id:"elders-13", title:"Finances being scammed", context:"Abena discovers her grandmother has sent £2,000 to an online ‘romance’ who needs money for a flight.", who:"older", level:3,
  jackal:"How could you be so gullible? It’s obviously a scam!",
  giraffe:{ o:"I saw you sent £2,000 to Michael for his flight.", f:"I feel worried", n:"because I want to protect you, and I know he’s been good company for you.", r:"Would you be willing to look at some information about these schemes with me before sending anything more?" },
  say:"Grandma, I saw you sent £2,000 to Michael. I know he’s made you feel less lonely, and I’m worried because this matches a common scam. Could we look at some information together before anything more goes?",
  empathy:"Are you lonely and enjoying feeling special and cared for?",
  tip:"Shame drives secrecy; protect dignity while addressing the risk, and contact the bank promptly." },
{ id:"elders-14", title:"Elder giving unwanted advice", context:"At every visit, Aunt Grace tells Mira she should lose weight to find a husband.", who:"older", level:2,
  jackal:"My weight is none of your business!",
  giraffe:{ o:"You’ve mentioned my weight and finding a husband on each of the last three visits.", f:"I feel hurt", n:"because I need acceptance and respect for my choices.", r:"Would you be willing to ask me about my work or travels instead?" },
  say:"Auntie, you’ve mentioned my weight the last few visits and it hurts. I know you want me happy. Could you ask me about my work or my trip instead? I’d love to tell you about it.",
  empathy:"Are you wanting me to be happy and secure in the way you understand it?",
  tip:"Give an alternative topic — it redirects care into a form you can receive." },
{ id:"elders-15", title:"Grandparent wants more time", context:"Grandpa Hiroshi complains that he only sees his grandchildren at holidays.", who:"older", level:1,
  jackal:"We’re busy — you could visit us too, you know.",
  giraffe:{ o:"You said you only see the kids at holidays.", f:"I hear you feel sad", n:"and want closeness with them.", r:"Would you like a weekly video call on Sundays, and a visit next month?" },
  say:"You only see them at holidays — I can hear that makes you sad. How about a video call every Sunday, and we plan a visit next month?",
  empathy:"Are you feeling left out and wanting to be part of their lives?",
  tip:"Offer something regular and small rather than promising big visits." },
{ id:"elders-16", title:"End-of-life wishes talk", context:"Sunita wants to ask her healthy 75-year-old father about his end-of-life wishes, but he changes the subject.", who:"older", level:2,
  jackal:"You can’t keep avoiding this, Dad.",
  giraffe:{ o:"When I mentioned planning ahead, you changed the subject.", f:"I feel uneasy", n:"because I want to honour your wishes if I ever need to decide for you.", r:"Would you be willing to talk about it for 15 minutes next Sunday?" },
  say:"Dad, I know it’s not a fun topic. I’d feel so much calmer knowing your wishes, so I can honour them one day. Could we give it fifteen minutes next Sunday?",
  empathy:"Are you uncomfortable thinking about death and wanting to enjoy life now?",
  tip:"Frame it as a gift to the family; set a time limit to lower the stakes." },
{ id:"elders-17", title:"Mum’s hoarding", context:"Ana’s mother’s flat is now so full of newspapers that the hallway is a fire risk.", who:"older", level:3,
  jackal:"This place is a dump. I’m getting a skip.",
  giraffe:{ o:"The hallway is stacked with newspapers to shoulder height.", f:"I feel worried", n:"because I want you safe if there’s a fire, and your things clearly matter to you.", r:"Would you choose one shelf with me today to sort through together?" },
  say:"Mãe, the hallway stacks are up to my shoulder and I’m worried about fire. I know these matter to you. Could we pick just one shelf today and sort it together, with you deciding what stays?",
  empathy:"Are you needing security, and do these things hold memories that feel important?",
  tip:"Never clear without consent; small, collaborative steps build trust." },
{ id:"elders-18", title:"Ignored at the family table", context:"At a big dinner, Grandma Ruth sits quietly while conversations about phones and apps flow past her.", who:"older", level:1,
  jackal:"(Thinking) She’s fine, she’s just tired.",
  giraffe:{ o:"You haven’t said much during dinner.", f:"I wonder if you feel left out", n:"and want to be included.", r:"Would you tell us about your first job?" },
  say:"Grandma, we’ve been chatting tech all night — what was your very first job like? I’d love to hear.",
  empathy:"Are you feeling left out and wanting to belong?",
  tip:"Bring elders in with questions about their experience, not just about their health." },
{ id:"elders-19", title:"Elder abuse suspicion", context:"Visiting her neighbour Mr. Ortiz, Chloe notices bruises and that his son speaks sharply to him.", who:"older", level:3,
  jackal:"(To son) What are you doing to him?",
  giraffe:{ o:"I noticed bruises on your arm and you seemed quiet when your son spoke.", f:"I feel concerned", n:"because I care about your safety.", r:"Would you be willing to tell me how things are at home, just between us?" },
  say:"Mr. Ortiz, I noticed some bruises on your arm, and I care about you. How are things at home? It’s just between us, and I’m here to help however you’d like.",
  empathy:"Are you scared or ashamed and needing safety and support?",
  tip:"Speak privately and know your local adult safeguarding contact; you don’t need proof to raise a concern." },
{ id:"elders-20", title:"Siblings dispute care home", context:"Two brothers, Kofi and Yaw, argue: one wants their mother at home with carers, the other wants a care home.", who:"peer", level:3,
  jackal:"You just want the cheapest option.",
  giraffe:{ o:"We have different ideas about where Mum should live.", f:"I feel stressed", n:"because I want what’s best for Mum and for us to stay close.", r:"Would you list with me what matters most to Mum, then compare both options against it?" },
  say:"We both want what’s best for Mum, we just see it differently, and I’m stressed about it. Could we write down what matters most to her and then compare both options against that list?",
  empathy:"Are you worried about her safety and feeling the weight of this decision?",
  tip:"Separate needs (safety, connection, dignity) from strategies (home vs care home) before choosing." },
{ id:"elders-21", title:"Grandchild ignored for cousin", context:"Ten-year-old Ines tells her mum Grandma always praises cousin Bea and never her.", who:"child", level:2,
  jackal:"Don’t be silly, Grandma loves you both the same.",
  giraffe:{ o:"You said Grandma praised Bea’s drawing and didn’t mention yours.", f:"You sound hurt", n:"and want to be noticed and valued too.", r:"Would you like to show me your drawing now, and think together about telling Grandma?" },
  say:"Grandma talked about Bea’s drawing and not yours — that sounds like it really stung. I’d love to see yours. Shall we think together about whether to tell Grandma how it felt?",
  empathy:"Are you feeling left out and wanting to matter to Grandma?",
  tip:"Validate before reassuring; reassurance alone can feel like dismissal." },
{ id:"elders-22", title:"Father won’t move in", context:"After a fall, Maya invites her stubborn father to live with her. He refuses: ‘I’m not a burden.’", who:"older", level:2,
  jackal:"You’re being ridiculous, Dad — you can’t manage alone.",
  giraffe:{ o:"You said you don’t want to be a burden.", f:"I feel touched and also worried", n:"because I want you safe and I’d genuinely enjoy having you around.", r:"Would you try staying with us for two weeks and see how it feels?" },
  say:"Dad, you’d never be a burden — I’d honestly love having you here, and I worry after your fall. How about trying two weeks with us and seeing how it feels?",
  empathy:"Are you needing independence and to feel you still contribute?",
  tip:"Propose a trial period; it lowers the stakes and preserves choice." }
]},
{ id:"community", name:"Community & Neighbours", icon:"🏘️", hue:120, blurb:"Handle the friction of shared walls, streets and committees while keeping neighbourly goodwill.", cases:[
{ id:"community-01", title:"Late-night music upstairs", context:"For the third night this week, Bastian’s upstairs neighbour Chiara plays music until 1am.", who:"adult", level:1,
  jackal:"Some of us have jobs! Turn that racket down!",
  giraffe:{ o:"On Monday, Wednesday and tonight I could hear music in my bedroom until about 1am.", f:"I feel exhausted", n:"because I need sleep before my early shifts.", r:"Would you be willing to turn it down after 11 on weeknights?" },
  say:"Hi Chiara, sorry to knock — this week I’ve heard music in my bedroom until about 1am a few nights, and I’m exhausted for my early shifts. Could you turn it down after 11 on weeknights?",
  empathy:"Are you unwinding after work and wanting to enjoy your own home?",
  tip:"Knock in daylight, not at 1am mid-anger; the same words land very differently." },
{ id:"community-02", title:"Blocked driveway", context:"A visitor’s car is parked across Mrs. Osei’s driveway for the second time; she needs to leave for a hospital appointment.", who:"adult", level:2,
  jackal:"Move your car NOW or I’m calling a tow truck!",
  giraffe:{ o:"Your car is across my driveway and I need to leave in ten minutes.", f:"I’m stressed", n:"because I need to get to my hospital appointment on time.", r:"Could you move it now, please?" },
  say:"Hello — your car is across my driveway and I need to leave in ten minutes for a hospital appointment. I’m a bit stressed. Could you move it now, please?",
  empathy:"Were you finding it hard to get parking and didn’t realise it blocked me?",
  tip:"In urgent moments, keep it short: fact, time, request." },
{ id:"community-03", title:"Dog barking all day", context:"While working from home, Nadia hears next door’s dog barking for hours after the owner, Phil, leaves.", who:"adult", level:2,
  jackal:"Your dog is a nightmare. You shouldn’t own a pet if you leave it all day.",
  giraffe:{ o:"Most weekdays your dog barks from about 9 until noon after you leave.", f:"I feel frazzled", n:"because I need quiet to work, and I also wonder if the dog is distressed.", r:"Would you be open to me sending you a short recording so you can hear it?" },
  say:"Hi Phil, I work from home and most weekdays your dog barks from about nine till noon. I’m frazzled, and I also wonder if she’s anxious alone. Would it help if I sent you a short recording?",
  empathy:"Are you unaware of it, and would you want your dog to feel calm while you’re out?",
  tip:"Owners often genuinely don’t know; offer information before complaints." },
{ id:"community-04", title:"Fence on property line", context:"Neighbour Mr. Abubakar has started building a fence that Charlotte believes is half a metre on her side.", who:"adult", level:3,
  jackal:"You’re stealing my land! I’ll see you in court.",
  giraffe:{ o:"The new posts look to be about half a metre past where I understood the boundary to be.", f:"I feel uneasy", n:"because I need clarity and fairness, and I want to stay on good terms.", r:"Would you be willing to pause building until we check the deeds together this week?" },
  say:"I may be wrong, but the new posts look about half a metre past where I thought our boundary was, and I feel uneasy. I’d hate to fall out over it — could we pause and check the deeds together this week?",
  empathy:"Are you wanting privacy and to finish the project you’ve been planning?",
  tip:"Say ‘I may be wrong’ — it invites joint checking instead of defence." },
{ id:"community-05", title:"Mosque parking complaints", context:"Neighbours complain to Imam Farouk that Friday prayers fill the street with cars.", who:"group", level:2,
  jackal:"You’re just complaining because you don’t like Muslims.",
  giraffe:{ o:"Several of you have said the street fills with cars on Friday afternoons.", f:"I feel concerned", n:"because we want to be good neighbours and for everyone to get around easily.", r:"Would you join a short meeting next week to agree on a parking plan together?" },
  say:"I hear that Friday afternoons the street gets packed, and that matters to us — we want to be good neighbours. Could some of you join a short meeting next week so we can agree on a parking plan together?",
  empathy:"Are you frustrated about access to your homes and needing consideration?",
  tip:"Separate a practical complaint from identity; respond to the practical need first." },
{ id:"community-06", title:"Volunteer not pulling weight", context:"At the food bank, volunteer Gareth has missed his last three shifts without notice.", who:"peer", level:2,
  jackal:"If you can’t be reliable, don’t bother volunteering.",
  giraffe:{ o:"You weren’t at your last three Saturday shifts and we didn’t get a message.", f:"I felt stretched and a bit worried", n:"because we need reliability to serve families, and I wondered if you were okay.", r:"Would you let me know by Thursday whether Saturdays still work for you?" },
  say:"Hi Gareth, we missed you at the last three Saturday shifts and didn’t hear anything — I was worried and we were stretched thin. Could you let me know by Thursday if Saturdays still work for you?",
  empathy:"Is life busier than expected and are you feeling awkward about stepping back?",
  tip:"Volunteers stay when they feel wanted; ask about their situation, not just attendance." },
{ id:"community-07", title:"Shared garden mess", context:"In a shared courtyard, a neighbour keeps leaving bin bags by the bench, attracting foxes.", who:"group", level:1,
  jackal:"Whoever keeps dumping rubbish here is disgusting.",
  giraffe:{ o:"Bin bags have been left by the bench three times this week and foxes tore one open.", f:"I feel frustrated", n:"because I want a clean, pleasant space we can all enjoy.", r:"Would everyone be willing to take bags straight to the main bins?" },
  say:"Hi all — bin bags have been left by the bench three times this week and the foxes got into one. I’d love this to stay a nice space. Could we all take bags straight to the main bins?",
  empathy:"Is it hard to get to the main bins, and would an easier option help?",
  tip:"In group notes, describe the issue, not the culprit, and check whether there’s an access barrier." },
{ id:"community-08", title:"Council meeting heckling", context:"At a town hall on a new bike lane, resident Mr. Price shouts down the cycling advocate, Aiko.", who:"adult", level:3,
  jackal:"Let her speak, you dinosaur!",
  giraffe:{ o:"Aiko has been interrupted several times before finishing her point.", f:"I feel uneasy", n:"because I want everyone to be heard so we can make a good decision.", r:"Would you be willing to let her finish, and then I’ll make sure you get the floor next?" },
  say:"Mr. Price, I can see you feel strongly about this. Aiko’s been interrupted a few times — could we let her finish, and then you take the floor next?",
  empathy:"Are you worried about your business or access and needing your concerns taken seriously?",
  tip:"Promise the interrupter a turn; it addresses their fear of not being heard." },
{ id:"community-09", title:"Neighbour’s tree over garden", context:"Gita’s neighbour’s oak drops branches into her children’s play area.", who:"adult", level:1,
  jackal:"Your tree is going to hurt my kids. Cut it down.",
  giraffe:{ o:"Two branches from the oak fell into the play area this month.", f:"I feel nervous", n:"because I need the children to be safe while playing.", r:"Would you be willing to have a tree surgeon look at it, and could we share the cost?" },
  say:"Two branches from your oak fell into the kids’ play area this month and I’m nervous. Would you be open to a tree surgeon looking at it? I’m happy to share the cost.",
  empathy:"Do you love the tree and want to protect it?",
  tip:"Offering to share cost signals partnership, not blame." },
{ id:"community-10", title:"Church committee power play", context:"At the parish committee, long-time member Doreen dismisses new ideas from younger members: ‘We’ve always done it this way.’", who:"group", level:2,
  jackal:"That’s why young people don’t come anymore.",
  giraffe:{ o:"The last three ideas from newer members were turned down with ‘we’ve always done it this way.’", f:"I feel discouraged", n:"because I want everyone to have a voice and for the church to grow.", r:"Would you be willing to trial one new idea for a month and review it together?" },
  say:"Doreen, I really value all you’ve built here. The last few ideas were set aside with ‘we’ve always done it this way,’ and I feel discouraged. Could we trial one for a month and review it together?",
  empathy:"Are you worried about losing traditions that have meaning for you?",
  tip:"A time-limited trial reduces fear of permanent change." },
{ id:"community-11", title:"Kids playing ball near car", context:"Neighbour kids, Tomás and Lily, keep kicking a football against Mr. Grant’s new car.", who:"child", level:1,
  jackal:"Oi! Get away from my car or I’ll tell your parents!",
  giraffe:{ o:"The ball has hit my car three times in the last few minutes.", f:"I feel worried", n:"because I want my car to stay undamaged.", r:"Would you play down by the green instead?" },
  say:"Hey you two — the ball’s hit my car a few times and I’m worried about dents. Could you play down by the green? There’s loads more space there.",
  empathy:"Are you just wanting a good place to play?",
  tip:"Kids respond better to a clear alternative than a threat." },
{ id:"community-12", title:"Gossip at school gate", context:"Parent Samira hears another parent spreading a rumour that her family is ‘getting a divorce’.", who:"peer", level:2,
  jackal:"Mind your own business, you gossip.",
  giraffe:{ o:"I heard you told some parents my husband and I are divorcing.", f:"I feel hurt and uncomfortable", n:"because I value privacy and honesty.", r:"Would you be willing to come to me directly if you’re curious about my family?" },
  say:"I heard that you mentioned to some parents that we’re divorcing, and I felt hurt. I value my family’s privacy. If you’re ever curious, could you just ask me directly?",
  empathy:"Were you wanting to feel connected or concerned for us?",
  tip:"Address gossip privately and with a clear request; publicly it often escalates." },
{ id:"community-13", title:"Smell from takeaway extractor", context:"A new restaurant’s extractor fan vents cooking smells straight into Rosa’s bedroom window.", who:"adult", level:2,
  jackal:"Your stink is ruining my home. I’m reporting you.",
  giraffe:{ o:"Since you opened, cooking smells come into my bedroom from about 5pm to midnight.", f:"I feel frustrated", n:"because I need comfort and fresh air in my home.", r:"Would you be willing to check whether the fan can be redirected or filtered?" },
  say:"Congratulations on opening! Since then, cooking smells come into my bedroom from five till midnight and I’m frustrated. Could you check whether the fan could be filtered or angled away?",
  empathy:"Are you working hard to get your business going and wanting to keep good relations?",
  tip:"Talk to the business first; escalate to the council only if needed." },
{ id:"community-14", title:"Neighbour feeding pigeons", context:"Old Mr. Fischer feeds pigeons from his balcony and droppings cover the balconies below.", who:"older", level:2,
  jackal:"Stop feeding those rats with wings!",
  giraffe:{ o:"There are pigeon droppings on my balcony every day since the feeding started.", f:"I feel annoyed", n:"because I want to use my balcony and keep it clean.", r:"Would you consider feeding them in the park instead?" },
  say:"Herr Fischer, I can tell you love those birds. Since the feeding started my balcony’s covered in droppings every day. Would you consider feeding them in the park instead?",
  empathy:"Are the birds company for you, meeting a need for connection?",
  tip:"Guess the need behind the behaviour (here, companionship) and suggest a strategy that keeps it." },
{ id:"community-15", title:"Political sign vandalised", context:"Someone has torn down the election sign in Kemal’s front garden; he suspects the neighbour opposite.", who:"adult", level:3,
  jackal:"I know it was you. Grow up!",
  giraffe:{ o:"My sign was torn down overnight.", f:"I feel upset", n:"because I value freedom of expression and respect between neighbours.", r:"Would you be willing to talk about the election over coffee, even though we disagree?" },
  say:"My sign got torn down last night and I’m upset — I don’t know who did it, but I value us being able to disagree respectfully. Would you have a coffee with me sometime and talk about the election?",
  empathy:"Do you feel strongly about what’s at stake and worried about the future?",
  tip:"Don’t accuse without evidence; invite connection across difference instead." },
{ id:"community-16", title:"Clashing over shared laundry", context:"In the building laundry room, Mei finds her wet clothes dumped on the floor by another tenant.", who:"peer", level:1,
  jackal:"Who throws someone’s clothes on the floor? Rude.",
  giraffe:{ o:"My wet laundry was taken out and left on the floor.", f:"I feel annoyed", n:"because I want consideration for my things.", r:"Would you leave a note or text me next time, and I’ll come down straight away?" },
  say:"Hi — my wet washing ended up on the floor, which annoyed me. I know waiting is frustrating. Next time could you text me? Here’s my number; I’ll come right down.",
  empathy:"Were you short on time and needing the machine?",
  tip:"Give a practical channel (a number, a sign-up sheet) to prevent repeats." },
{ id:"community-17", title:"Neighbour’s domestic shouting", context:"Through the wall, Julia hears repeated shouting and crashes next door late at night.", who:"adult", level:3,
  jackal:"(Bangs wall) Shut up in there!",
  giraffe:{ o:"I heard shouting and something crashing last night around midnight.", f:"I felt worried", n:"because I care about your safety.", r:"Are you okay, and is there anything you’d like help with?" },
  say:"Hi, I heard shouting and a crash around midnight and I was worried. Are you okay? If you ever need anything, I’m right next door.",
  empathy:"Could you be scared or ashamed, needing safety and support?",
  tip:"If you believe someone is in danger, call emergency services first; talk later." },
{ id:"community-18", title:"Allotment rule breaker", context:"At the community allotments, plot-holder Bruno has extended his shed onto the shared path.", who:"peer", level:2,
  jackal:"You think rules don’t apply to you?",
  giraffe:{ o:"The shed now reaches about a metre into the shared path.", f:"I feel frustrated", n:"because I want access for everyone, including wheelbarrows and wheelchairs.", r:"Would you be willing to move it back by the end of the month?" },
  say:"Bruno, the shed reaches about a metre onto the shared path now and it’s hard to get barrows and wheelchairs past. Could you move it back by the end of the month?",
  empathy:"Do you need more storage space and didn’t realise the impact?",
  tip:"Name who is affected; it moves the issue from rules to people." },
{ id:"community-19", title:"Accused of racism in group", context:"In a residents’ group, Thandiwe says Paul’s comment about ‘those families’ was racist. Paul feels defensive.", who:"group", level:3,
  jackal:"I’m not racist! How dare you?",
  giraffe:{ o:"You said my comment about ‘those families’ sounded racist.", f:"I feel uncomfortable", n:"and I want to understand and to treat everyone with respect.", r:"Would you tell me how it landed for you?" },
  say:"Ouch — I’m uncomfortable hearing that, and I want to understand. Respect for everyone matters to me. Would you tell me how my comment landed for you?",
  empathy:"Are you feeling hurt and needing respect for your community?",
  tip:"Curiosity first, defence later (or never) — impact matters even when intent was different." },
{ id:"community-20", title:"Noisy building work", context:"Builders next door start drilling at 7am on a Saturday. Helen’s baby has just fallen asleep.", who:"adult", level:2,
  jackal:"It’s seven on a Saturday! Are you serious?",
  giraffe:{ o:"The drilling started at 7am today.", f:"I feel exasperated", n:"because I need rest for my baby and me.", r:"Would you be willing to start the loud work after 9 on weekends?" },
  say:"Morning — the drilling started at seven and my baby had only just gone down. I’m exhausted. Could the loud work start after nine at weekends?",
  empathy:"Are you under pressure to finish the job on schedule?",
  tip:"Check local noise rules beforehand; knowing them helps you ask calmly." },
{ id:"community-21", title:"Scout leader yells at child", context:"At scouts, leader Mr. Bishop shouts at ten-year-old Ravi in front of the group.", who:"adult", level:2,
  jackal:"You can’t speak to kids like that!",
  giraffe:{ o:"I heard you shout at Ravi in front of the group.", f:"I felt uneasy", n:"because I want all the kids to feel safe and respected.", r:"Would you be willing to talk about other ways to handle it next time?" },
  say:"Mr. Bishop, I heard you shout at Ravi in front of the group and I felt uneasy — I know you care about these kids. Could we chat about other ways to handle it?",
  empathy:"Were you feeling frustrated and needing cooperation?",
  tip:"Raise it privately and promptly; include your appreciation for the volunteer’s commitment." },
{ id:"community-22", title:"New neighbours unfriendly", context:"Isabella waves at her new neighbours twice; they don’t respond.", who:"adult", level:1,
  jackal:"(Thinking) Snobs. I won’t bother again.",
  giraffe:{ o:"You moved in last week and we haven’t properly met yet.", f:"I feel happy and a little shy", n:"because I value friendly connection on our street.", r:"Would you like to come over for tea on Saturday afternoon?" },
  say:"Hi! I’m Isabella from number 12 — welcome! I realised we haven’t properly met and I’d love to. Would you like to come over for tea on Saturday afternoon?",
  empathy:"Could they be shy, busy or not sure who I am, needing time to settle in?",
  tip:"Assume ambiguity, not rejection; make one clear friendly gesture before deciding." }
]},
{ id:"digital", name:"Digital & Social Media", icon:"📱", hue:265, blurb:"Bring warmth and clarity to chats, comments and feeds, where tone gets lost and reactions spread fast.", cases:[
{ id:"digital-01", title:"Left on read", context:"Ella messaged her friend Jun about weekend plans two days ago; it shows ‘read’ but no reply.", who:"peer", level:1,
  jackal:"Wow, nice to know I’m not worth a reply.",
  giraffe:{ o:"I sent you a message about the weekend on Tuesday and haven’t heard back.", f:"I feel a bit unsure", n:"because I value knowing where I stand and making plans with you.", r:"Would you let me know by Friday if Saturday still works?" },
  say:"Hey Jun! Just checking about Saturday — no pressure, I’d just love to know by Friday so I can plan. 😊",
  empathy:"Are you overwhelmed this week and needing space without guilt?",
  tip:"‘Read’ receipts tell you a message was opened, not what someone feels. Ask lightly, once." },
{ id:"digital-02", title:"Uncle shares misinformation", context:"Uncle Raj posts a viral health claim in the family WhatsApp that Anika knows is false.", who:"older", level:2,
  jackal:"This is fake news. Please check before you post nonsense.",
  giraffe:{ o:"The video you shared says a herbal drink cures diabetes.", f:"I feel worried", n:"because I care about everyone’s health and want us to have reliable information.", r:"Would you be willing to look at this fact-check with me and talk about it at Sunday lunch?" },
  say:"Uncle, I know you shared this because you care about us. I’m a bit worried because the claim that this drink cures diabetes has been checked and isn’t supported. Could we chat about it at Sunday lunch? I’ve got the fact-check here.",
  empathy:"Are you wanting to protect the family and share something hopeful?",
  tip:"Correct privately when possible; public corrections in family chats often trigger face-saving." },
{ id:"digital-03", title:"Comment war on post", context:"A stranger replies to Diego’s post about climate policy calling him ‘a brainwashed idiot’.", who:"adult", level:2,
  jackal:"Says the guy who can’t spell. Educate yourself.",
  giraffe:{ o:"You called me a brainwashed idiot in your reply.", f:"I feel uncomfortable", n:"because I value respectful debate.", r:"Would you be willing to share what worries you about the policy?" },
  say:"Name-calling won’t help either of us. I’m genuinely curious though — what worries you most about this policy?",
  empathy:"Are you worried about costs or your livelihood and needing your concerns heard?",
  tip:"You don’t owe every comment a response. Reply once with curiosity, or mute and move on." },
{ id:"digital-04", title:"Teen cyberbullied", context:"Thirteen-year-old Hana comes home crying; classmates made a group chat mocking her photos.", who:"teen", level:3,
  jackal:"I’ll call those kids’ parents right now!",
  giraffe:{ o:"You’re crying and you told me there’s a group chat making fun of your photos.", f:"You sound really hurt and embarrassed", n:"and you need to feel safe and accepted.", r:"Would you show me what’s been said, so we can decide together what to do next?" },
  say:"Oh, love. A group chat mocking your photos — that’s really hurtful. I’m so glad you told me. Would you show me what’s been said, and we’ll decide together what happens next?",
  empathy:"Are you feeling humiliated and needing belonging and protection?",
  tip:"Screenshot evidence and involve the teen in decisions; taking over can stop them telling you next time." },
{ id:"digital-05", title:"Friend overshares your news", context:"Riya posts Mila’s pregnancy announcement on Instagram before Mila has told her own parents.", who:"peer", level:3,
  jackal:"You had no right! You’ve ruined everything.",
  giraffe:{ o:"You posted about my pregnancy before I’d told my parents.", f:"I feel shocked and upset", n:"because I need privacy and to share my news in my own way.", r:"Would you take the post down now?" },
  say:"Riya, I saw you posted about my pregnancy — I haven’t told my parents yet and I’m really upset. Could you take it down right now? We can talk properly later.",
  empathy:"Were you excited and wanting to celebrate me?",
  tip:"Make the urgent request first; the deeper conversation can wait until you’re calmer." },
{ id:"digital-06", title:"Excluded from group chat", context:"Tomasz discovers his friends have a separate group chat for planning trips without him.", who:"peer", level:2,
  jackal:"Guess I know who my real friends are.",
  giraffe:{ o:"I saw there’s a group chat planning the camping trip that I’m not in.", f:"I feel hurt and left out", n:"because I value belonging with you guys.", r:"Would you be willing to tell me what happened?" },
  say:"Hey, I noticed there’s a group planning the camping trip that I’m not part of. Honestly I felt left out. Can you help me understand what happened?",
  empathy:"Was it a mistake, or are there tensions they find hard to raise?",
  tip:"Ask before assuming; there’s often a simple explanation — and if not, you’ll learn something useful." },
{ id:"digital-07", title:"Child gaming for hours", context:"Eleven-year-old Kai has been on his console for four hours and screams when asked to stop.", who:"child", level:2,
  jackal:"That’s it, I’m throwing that thing in the bin!",
  giraffe:{ o:"You’ve been playing since 2pm, and it’s now 6.", f:"I feel concerned", n:"because I care about balance for you, and I know how much you love this game.", r:"Would you find a save point in the next five minutes, then help me with dinner?" },
  say:"You’ve been playing since two and it’s six now. I know you’re in the middle of it — can you find a save point in the next five minutes, then come help me with dinner?",
  empathy:"Are you absorbed and wanting to finish with your team?",
  tip:"Give a heads-up before stopping; abrupt cutoffs in online games feel like letting friends down." },
{ id:"digital-08", title:"Boss texts at midnight", context:"Manager Greg messages Aisha at 11:45pm asking for an urgent report tweak.", who:"adult", level:2,
  jackal:"Do you ever sleep? I’m not your slave.",
  giraffe:{ o:"I got your message about the report at 11:45 last night.", f:"I felt tense", n:"because I need rest to do good work, and I want to support the team.", r:"Would you be willing to send non-urgent requests during work hours, and call me if it’s a real emergency?" },
  say:"Morning Greg — I saw your 11:45 message and I’ll get the tweak done this morning. I find late messages hard to switch off from. Could non-urgent things come in work hours, and you call me if it’s a genuine emergency?",
  empathy:"Are you under pressure and worried about the deadline?",
  tip:"Distinguish urgent from non-urgent explicitly; it gives the other person a clear alternative." },
{ id:"digital-09", title:"Ex posts about you", context:"Jamal’s ex posts a vague but obvious story about ‘toxic men who lie’.", who:"adult", level:3,
  jackal:"(Posts back) At least I’m not a psycho.",
  giraffe:{ o:"I saw a post that seemed to be about me.", f:"I feel hurt and angry", n:"because I value dignity and moving on peacefully.", r:"Would I be willing to mute their account and talk to a friend instead of replying?" },
  say:"(To himself, then to a friend) I’m hurt and angry about that post. I want to keep my dignity, so I’m going to mute it and talk to you instead of responding.",
  empathy:"Could they be in pain and needing validation for their experience?",
  tip:"Sometimes the best giraffe move is not posting. Self-empathy first, then decide." },
{ id:"digital-10", title:"Coworker misreads tone", context:"Maya’s brief Slack reply ‘fine’ gets her teammate Oluwaseun asking if she’s angry.", who:"peer", level:1,
  jackal:"Why are you so sensitive? I said it’s fine.",
  giraffe:{ o:"You asked if I was angry after my ‘fine’ message.", f:"I feel sorry", n:"because I value clear, warm communication with you.", r:"Would you be willing to ask me like this whenever something reads off?" },
  say:"Ah, sorry — I was rushing between meetings, not angry at all! I really appreciate you checking. Please keep asking me if something reads off.",
  empathy:"Were you worried you’d upset me and wanting to stay connected?",
  tip:"Text strips out tone; when in doubt, add a few words or an emoji to show warmth." },
{ id:"digital-11", title:"Parent posts child photos", context:"Fifteen-year-old Sofia is upset that her dad posted her childhood bath photo on Facebook.", who:"teen", level:2,
  jackal:"It’s cute! You’re overreacting.",
  giraffe:{ o:"You said you’re upset about the photo I posted.", f:"You sound embarrassed", n:"and want privacy and say over your own image.", r:"Would you like me to delete it now and check with you before I post photos of you?" },
  say:"You’re really upset about that photo — I get it, you want a say in what’s out there about you. I’ll delete it now. From now on I’ll check with you before posting any photos of you, okay?",
  empathy:"Are you feeling exposed and needing respect for your growing independence?",
  tip:"Ask consent before posting kids’ photos — it models digital respect." },
{ id:"digital-12", title:"Online gaming toxicity", context:"In an online match, a teammate types slurs at 14-year-old Leo after a loss.", who:"teen", level:2,
  jackal:"Get good, you loser. Uninstall.",
  giraffe:{ o:"You typed insults at me after we lost.", f:"I feel annoyed", n:"because I want gaming to be fun and respectful.", r:"Would you keep it to strategy chat next round?" },
  say:"Not cool, mate. Let’s keep chat to tactics next round — I want this to be fun.",
  empathy:"Are you frustrated about losing and wanting to win?",
  tip:"Report slurs, use mute, and talk with a trusted adult — you don’t have to absorb abuse." },
{ id:"digital-13", title:"Friend ignores in group", context:"In a group chat, everyone reacts to messages except Laila’s — her posts get no responses.", who:"peer", level:2,
  jackal:"Guess I’ll just talk to myself then.",
  giraffe:{ o:"My last three messages didn’t get any replies.", f:"I feel a bit invisible and sad", n:"because I value feeling included.", r:"Would one of you tell me if something’s up?" },
  say:"Hey, maybe I’m imagining it, but my last few messages got no replies and I felt a bit invisible. Is something up?",
  empathy:"Could others be busy, or is there something they find hard to say?",
  tip:"Try a private message to one trusted member first — less exposure than asking the whole group." },
{ id:"digital-14", title:"Partner always on phone", context:"During dinner, Aleksander scrolls his phone while Bea talks about her day.", who:"adult", level:1,
  jackal:"Am I boring you? Marry your phone then.",
  giraffe:{ o:"You were looking at your phone while I told you about my day.", f:"I feel lonely", n:"because I want connection with you at dinner.", r:"Would you be willing to put phones away during meals?" },
  say:"Love, I was telling you about my day and you were on your phone — I felt a bit lonely. Could we keep phones off the table at dinner?",
  empathy:"Are you stressed about something and needing distraction?",
  tip:"Suggest a shared rule rather than policing one person." },
{ id:"digital-15", title:"Viral negative review", context:"A café owner, Hyun-woo, finds a one-star review calling his staff ‘rude and lazy’.", who:"adult", level:2,
  jackal:"Clearly you’re a liar who never even came here.",
  giraffe:{ o:"You wrote that our staff were rude and slow during your visit.", f:"I’m sorry and concerned", n:"because I want every customer to feel welcome.", r:"Would you be willing to email me so I can learn what happened?" },
  say:"Thank you for telling us — I’m sorry your visit felt that way. I want everyone to feel welcome here. Could you email me at the address below so I can understand what happened?",
  empathy:"Were you disappointed and needing respect or attention?",
  tip:"Public replies are also for future readers; calm empathy builds trust." },
{ id:"digital-16", title:"Sister’s political posts", context:"Nicole’s sister posts angry political memes daily that Nicole finds offensive.", who:"peer", level:2,
  jackal:"Your posts are hateful. I’m unfriending you.",
  giraffe:{ o:"I’ve seen several of your posts about immigration this week.", f:"I feel sad", n:"because I value our closeness and respect our different views.", r:"Would you be willing to talk about it over coffee instead of online?" },
  say:"Sis, I’ve seen your posts this week and I feel sad, because I care about us more than politics. Could we talk about it over coffee instead of online?",
  empathy:"Are you scared about the future and needing to feel heard?",
  tip:"Move hot topics offline; faces and voices soften what text hardens." },
{ id:"digital-17", title:"Teen sexting worry", context:"Fiona sees on her 15-year-old son Callum’s screen that a girl has asked him to send a photo.", who:"teen", level:3,
  jackal:"Give me that phone. You’re grounded.",
  giraffe:{ o:"I saw a message asking you to send a photo.", f:"I feel worried", n:"because I want you safe and I want you to feel you can come to me.", r:"Would you be willing to talk about it with me tonight?" },
  say:"Callum, I saw a message asking you for a photo. I’m not angry — I’m worried, and I want you to know you can talk to me. Can we chat tonight?",
  empathy:"Are you feeling embarrassed and needing privacy and understanding?",
  tip:"Calm, non-shaming talk keeps the line open; explain the legal and safety risks without lecturing." },
{ id:"digital-18", title:"Coworker forwards private email", context:"Pedro forwards Isha’s candid email about a project to the whole team.", who:"peer", level:2,
  jackal:"Thanks for throwing me under the bus.",
  giraffe:{ o:"You forwarded my email to the whole team.", f:"I feel embarrassed", n:"because I need trust and privacy in our communication.", r:"Would you ask me before sharing my messages in future?" },
  say:"Pedro, I saw my email went to the whole team and I felt embarrassed — I wrote it just for you. Could you check with me before forwarding my messages in future?",
  empathy:"Were you trying to be transparent and keep the team informed?",
  tip:"Name what’s at stake (trust) and give a clear future request." },
{ id:"digital-19", title:"Friend’s humblebrag fatigue", context:"Chidi’s friend constantly posts luxury holidays; Chidi feels envious and irritated.", who:"self", level:1,
  jackal:"(Thinking) What a show-off. Their life must be fake.",
  giraffe:{ o:"I’ve seen five holiday posts from them this month.", f:"I feel envious and a bit low", n:"because I need rest, adventure and to feel content with my life.", r:"Would I be willing to mute their posts for a while and plan a small trip of my own?" },
  say:"(To himself) I notice I’m envious when I see those posts. I’m craving adventure too. I’ll mute them for now and plan a weekend away.",
  empathy:"Could they be wanting to share joy or to feel seen?",
  tip:"Envy points to your own unmet needs — use it as a signpost, not a weapon." },
{ id:"digital-20", title:"Doxxing threat", context:"After a heated online exchange, a stranger tells Leah they’ve found her home address.", who:"adult", level:3,
  jackal:"Try it and see what happens!",
  giraffe:{ o:"You wrote that you know my home address.", f:"I feel scared", n:"because I need safety.", r:"(To platform/police) Would you help me report and block this account now?" },
  say:"(To the platform or police) Someone has written that they know my home address and I feel unsafe. Could you help me report and block this account now?",
  empathy:"Is the other person angry and seeking power or control?",
  tip:"Don’t engage threats; document, report and contact police if you feel unsafe." },
{ id:"digital-21", title:"Admin of chaotic group", context:"Gabriela runs a neighbourhood Facebook group where two members trade insults daily.", who:"group", level:2,
  jackal:"Both of you are banned. Pathetic.",
  giraffe:{ o:"There have been several insulting comments between members this week.", f:"I feel concerned", n:"because I want this group to be useful and respectful for everyone.", r:"Would you all keep comments to the topic and message each other privately if you disagree?" },
  say:"Hi everyone — there’ve been some insulting comments this week and I want this group to stay helpful and respectful. Please keep comments on topic and take disagreements to private messages. Thanks!",
  empathy:"Are members feeling unheard and wanting their views to matter?",
  tip:"Post clear group norms and enforce them consistently, not personally." },
{ id:"digital-22", title:"Child secret social account", context:"Malik discovers his 12-year-old daughter Zainab has a secret TikTok account.", who:"child", level:2,
  jackal:"You lied to me! No phone for a month.",
  giraffe:{ o:"I found your TikTok account that I didn’t know about.", f:"I feel worried and a bit hurt", n:"because I want you safe online and I value honesty between us.", r:"Would you show me your account and talk with me about how to make it safer?" },
  say:"Zainab, I found your TikTok account. I’m worried, and a little hurt you didn’t feel you could tell me. Can you show me what you post, and we’ll work out together how to keep it safe?",
  empathy:"Are you wanting to fit in with friends and have some independence?",
  tip:"Collaborative safety settings work better than secret surveillance." }
]},
{ id:"public", name:"Customer Service & Public", icon:"🛎️", hue:345, blurb:"Stay human with strangers behind counters, on phones and in queues — on both sides of the service desk.", cases:[
{ id:"public-01", title:"Angry customer at till", context:"A customer shouts at cashier Aliyu because a discount didn’t apply.", who:"adult", level:2,
  jackal:"Don’t shout at me — it’s not my fault.",
  giraffe:{ o:"The discount didn’t come through on your receipt.", f:"I can see you’re frustrated", n:"and want to be charged fairly.", r:"Would you let me call my supervisor to fix it now?" },
  say:"The discount didn’t come off — I can see that’s really frustrating, and you want to be charged correctly. Let me call my supervisor to sort it right now.",
  empathy:"Are you stressed and needing fairness and respect?",
  tip:"Repeat the core issue back briefly; feeling understood usually lowers volume." },
{ id:"public-02", title:"Rude waiter", context:"Waiter sighs loudly and rolls his eyes when Pooja asks to change her order.", who:"adult", level:1,
  jackal:"Is it too much trouble for you to do your job?",
  giraffe:{ o:"When I asked to change my order, I heard a sigh.", f:"I felt a bit awkward", n:"because I want to feel welcome here.", r:"Would it still be possible to swap the pasta for the risotto?" },
  say:"Sorry to change things — I’m feeling a bit awkward. Would it still be possible to swap the pasta for the risotto?",
  empathy:"Are you overwhelmed with a busy shift and needing ease?",
  tip:"Sometimes a simple, warm request without commentary resets the interaction." },
{ id:"public-03", title:"Delayed train announcement", context:"Commuters crowd a station worker, Grace, when a train is cancelled for the third time this week.", who:"group", level:2,
  jackal:"This service is a joke. You should all be fired!",
  giraffe:{ o:"This is the third cancellation on this line this week.", f:"I’m frustrated and tired", n:"because I need reliable transport to get to work.", r:"Could you tell me the fastest alternative route right now?" },
  say:"Third cancellation this week — I’m really frustrated, though I know it’s not your call. What’s the fastest alternative route for me right now?",
  empathy:"Are you facing angry crowds all day and needing respect too?",
  tip:"Frontline staff rarely control decisions; ask them for what they can give (information)." },
{ id:"public-04", title:"Landlord ignores repair", context:"Tenant Musa has reported black mould in his flat three times over two months; landlord hasn’t responded.", who:"adult", level:3,
  jackal:"You’re a slumlord. I’ll report you to the council.",
  giraffe:{ o:"I reported mould in the bedroom on 3 March, 20 March and 10 April, and haven’t had a reply.", f:"I feel worried and frustrated", n:"because I need a healthy home for my family.", r:"Would you arrange for someone to inspect it by next Friday and confirm in writing?" },
  say:"I’ve reported the bedroom mould three times since March without hearing back. I’m worried about my kids’ health. Could you arrange an inspection by next Friday and confirm in writing?",
  empathy:"Are you juggling many properties and feeling overstretched?",
  tip:"Keep dated records and give a clear deadline before escalating." },
{ id:"public-05", title:"Contractor overruns", context:"Builder Dariusz says the kitchen will take three more weeks than agreed, and cost more.", who:"adult", level:2,
  jackal:"You’re ripping me off. This is unacceptable.",
  giraffe:{ o:"The schedule has moved from 6 to 9 weeks and the quote has gone up 15%.", f:"I feel anxious", n:"because I need predictability and fairness.", r:"Would you show me the breakdown of extra costs and a revised timeline in writing?" },
  say:"Going from six to nine weeks and fifteen percent more is a lot, and I feel anxious. Could you show me what’s behind the extra cost and give me a revised timeline in writing?",
  empathy:"Did unexpected problems come up and are you worried about losing money too?",
  tip:"Request transparency rather than accusing; it often reveals real causes." },
{ id:"public-06", title:"Queue jumper", context:"At the post office, a man steps in front of Lucía, who has been waiting 20 minutes.", who:"adult", level:1,
  jackal:"Excuse me, are you blind? There’s a queue!",
  giraffe:{ o:"You stepped in front of me in the queue.", f:"I feel annoyed", n:"because I value fairness — we’ve all been waiting.", r:"Would you join the line at the back, please?" },
  say:"Excuse me — I think you might’ve missed the queue. We’ve all been waiting a while. Would you mind joining at the back?",
  empathy:"Maybe he didn’t see the line or is in a hurry?",
  tip:"Offer an easy out (‘you might’ve missed it’) so they can comply without losing face." },
{ id:"public-07", title:"Call centre runaround", context:"Kwabena has been transferred four times trying to cancel his internet contract.", who:"adult", level:2,
  jackal:"Are you all incompetent? I’ve been on hold an hour!",
  giraffe:{ o:"This is my fourth transfer in an hour.", f:"I feel exasperated", n:"because I need this resolved efficiently.", r:"Could you stay on the line until the cancellation is confirmed?" },
  say:"I know it’s not your fault — this is my fourth transfer in an hour and I’m exasperated. Could you stay on the line with me until the cancellation is confirmed?",
  empathy:"Are you following procedures and wanting to help within limits?",
  tip:"Ask the agent for their name and a reference number; it creates accountability calmly." },
{ id:"public-08", title:"Parking warden ticket", context:"A warden is writing a ticket as Anjali rushes back to her car, two minutes over.", who:"adult", level:2,
  jackal:"Two minutes! You people are vultures.",
  giraffe:{ o:"I see you’re writing a ticket and I’m two minutes over.", f:"I feel frustrated", n:"because I need understanding — I was at the pharmacy for my son.", r:"Would you be willing to cancel it, or tell me how to appeal?" },
  say:"I’m two minutes over — I was at the pharmacy for my son. I’m really frustrated. Would you be able to cancel it, or tell me how to appeal?",
  empathy:"Are you doing your job and needing respect?",
  tip:"Calm explanations open doors; even if not, ask for the appeal process." },
{ id:"public-09", title:"Bus driver refuses entry", context:"A bus driver tells Samuel, a wheelchair user, the ramp is ‘broken’ and drives off.", who:"adult", level:3,
  jackal:"(Shouting after bus) Discrimination!",
  giraffe:{ o:"The driver of route 12 at 8:15 said the ramp was broken and left without me.", f:"I feel angry and excluded", n:"because I need equal access to transport.", r:"(To the company) Would you investigate and tell me what you’ll do to prevent this?" },
  say:"I’m writing about route 12 at 8:15 today: the driver said the ramp was broken and left without me. I feel angry and excluded. Please investigate and tell me what you’ll do to prevent it happening again.",
  empathy:"Was the driver stressed or untrained and unsure how to help?",
  tip:"Record time, route and bus number; formal complaints lead to systemic change." },
{ id:"public-10", title:"Official at visa office", context:"A clerk tells Maryam her visa application is incomplete but won’t say what’s missing.", who:"adult", level:3,
  jackal:"How am I supposed to fix it if you won’t tell me?!",
  giraffe:{ o:"You said my application is incomplete.", f:"I feel confused and anxious", n:"because I need clarity to fix it.", r:"Could you point to the section or document that’s missing?" },
  say:"I want to get this right. You said it’s incomplete and I’m anxious because I don’t know what’s missing. Could you point to the section or document I need?",
  empathy:"Are you bound by rules and under pressure to process many cases?",
  tip:"Ask for specific references; bureaucracies run on forms and sections." },
{ id:"public-11", title:"Shop refuses refund", context:"A store manager refuses to refund Jean-Luc’s faulty kettle without a receipt.", who:"adult", level:2,
  jackal:"Your policy is a scam. I’m never shopping here again.",
  giraffe:{ o:"The kettle stopped working after a week and I don’t have the receipt.", f:"I feel disappointed", n:"because I need fairness.", r:"Would you check your system with my card payment, or offer an exchange?" },
  say:"It stopped working after a week and I’ve lost the receipt — I’m disappointed. Could you look it up from my card payment, or offer an exchange?",
  empathy:"Are you needing to follow policy and avoid fraud?",
  tip:"Offer alternatives the other side can say yes to." },
{ id:"public-12", title:"Drunk passenger harassing", context:"On a late train, a drunk man makes loud comments to a young woman, Ayumi, sitting alone.", who:"adult", level:3,
  jackal:"Leave her alone, you creep!",
  giraffe:{ o:"You’ve said several comments to her and she’s turned away.", f:"I feel uneasy", n:"because I want everyone to feel safe here.", r:"Would you take a seat further down?" },
  say:"(To Ayumi) Hey, mind if I sit here? (To the man, calmly) She’s turned away — let’s give her some space. How about taking a seat down there?",
  empathy:"Is he lonely or seeking attention and not reading cues?",
  tip:"Prioritise the target’s safety: sit with them, alert staff, avoid escalation." },
{ id:"public-13", title:"Customer racist remark", context:"A customer tells receptionist Priyanka to ‘go back where she came from’.", who:"adult", level:3,
  jackal:"Get out of here, you bigot!",
  giraffe:{ o:"You just told me to go back where I came from.", f:"I feel shocked and hurt", n:"because I need respect at work.", r:"I can help with your booking if we keep it respectful — would you like to continue?" },
  say:"That comment isn’t okay. I’m happy to help with your booking as long as we keep it respectful. Would you like to continue?",
  empathy:"Is he frustrated and taking it out on me?",
  tip:"You don’t have to give empathy to abuse in the moment — clear boundaries and involving a manager are valid." },
{ id:"public-14", title:"Hotel overbooked", context:"At midnight, the hotel tells Chukwuemeka his room isn’t available.", who:"adult", level:2,
  jackal:"I booked months ago! This is outrageous.",
  giraffe:{ o:"You’re saying my room isn’t available, and it’s midnight.", f:"I feel exhausted and stressed", n:"because I need rest and certainty.", r:"Could you book me into another hotel nearby and cover the taxi?" },
  say:"It’s midnight and I’m exhausted — I really need somewhere to sleep. Could you book me into a nearby hotel and cover the taxi?",
  empathy:"Are you embarrassed and wanting to help but limited?",
  tip:"Ask for the specific remedy you want; staff often have discretion they won’t volunteer." },
{ id:"public-15", title:"Library patron noise", context:"Librarian Nikos needs to ask a group of teens to lower their voices.", who:"teen", level:1,
  jackal:"Shh! This is a library, not a playground.",
  giraffe:{ o:"I can hear your conversation from the front desk.", f:"I feel a bit concerned", n:"because others here need quiet to focus.", r:"Would you use the group study room so you can chat freely?" },
  say:"Hey guys, I can hear you from the front desk and folks here need quiet. The group study room’s free — want to use it so you can chat freely?",
  empathy:"Are you working on something together and needing space to talk?",
  tip:"Offer a place to meet the need rather than just stopping the behaviour." },
{ id:"public-16", title:"Taxi overcharging", context:"A taxi driver quotes Emilia triple the usual fare at the airport.", who:"adult", level:2,
  jackal:"You’re trying to rip off tourists!",
  giraffe:{ o:"The fare you quoted is about three times what the app shows.", f:"I feel uneasy", n:"because I need fairness and transparency.", r:"Would you use the meter, please?" },
  say:"The app shows about a third of that, so I’m a bit uneasy. Could you use the meter, please?",
  empathy:"Is he wanting to earn enough after waiting a long time?",
  tip:"Refer to a neutral standard (meter, app) instead of accusing." },
{ id:"public-17", title:"Neighbourhood police stop", context:"A police officer stops 19-year-old Darnell walking home and asks what he’s doing.", who:"teen", level:3,
  jackal:"Why are you harassing me? I didn’t do anything!",
  giraffe:{ o:"You stopped me and asked what I’m doing.", f:"I feel nervous", n:"because I need safety and respect.", r:"Could you tell me why I’ve been stopped?" },
  say:"I’m just walking home from work. I’m feeling nervous — could you tell me why I’ve been stopped?",
  empathy:"Is the officer cautious and needing to feel safe?",
  tip:"Stay calm, keep hands visible, know your rights, and note badge numbers for later complaint if needed." },
{ id:"public-18", title:"Delivery left in rain", context:"Courier leaves Ursula’s laptop parcel on the doorstep in the rain.", who:"adult", level:1,
  jackal:"Who leaves a laptop in the rain? Idiot.",
  giraffe:{ o:"The parcel was left outside in the rain while I was home.", f:"I feel frustrated", n:"because I need my deliveries kept safe.", r:"Would you knock or ring next time before leaving it?" },
  say:"(Message to courier company) Today my laptop was left outside in the rain while I was home. I’m frustrated — could drivers knock or ring before leaving parcels in future?",
  empathy:"Was the courier rushing with many drops and under time pressure?",
  tip:"Give the company specific feedback they can pass on." },
{ id:"public-19", title:"Gym member hogging machine", context:"At the gym, a man has sat on the leg press scrolling his phone for 15 minutes.", who:"adult", level:1,
  jackal:"Some of us came to exercise, not text.",
  giraffe:{ o:"You’ve been on the leg press for about fifteen minutes.", f:"I feel impatient", n:"because I’d like to fit in my workout.", r:"Would you mind if I worked in between your sets?" },
  say:"Hey, mind if I work in between your sets? I’m on a tight schedule.",
  empathy:"Is he resting between sets and unaware of others waiting?",
  tip:"‘Working in’ is a common gym norm — offer to share, not oust." },
{ id:"public-20", title:"Clerk helps you poorly", context:"Bank teller seems distracted and gives Mohammed incorrect information about his account.", who:"adult", level:2,
  jackal:"You clearly don’t know what you’re doing.",
  giraffe:{ o:"The balance you gave me doesn’t match my app.", f:"I feel confused", n:"because I need accurate information.", r:"Could you check again, or ask a colleague?" },
  say:"Sorry, the balance you said doesn’t match my app, and I’m confused. Could you check again, or ask a colleague?",
  empathy:"Are they new and wanting to get it right?",
  tip:"Point to the discrepancy, not the person." },
{ id:"public-21", title:"You snapped at a customer", context:"Shop assistant Bea realises she snapped at an elderly customer earlier.", who:"older", level:2,
  jackal:"(Thinking) Whatever, she was annoying.",
  giraffe:{ o:"Earlier I spoke sharply when you asked about prices.", f:"I feel regretful", n:"because I value kindness and respect for everyone.", r:"Would you accept my apology and let me help you now?" },
  say:"I’m sorry I was sharp earlier when you asked about prices — I was stressed, but that’s no excuse. Can I help you find what you need now?",
  empathy:"Did she feel hurt and needing respect?",
  tip:"A specific apology (‘I spoke sharply’) repairs better than a general one." },
{ id:"public-22", title:"Neighbour store owner shortchanges", context:"Corner shop owner Mr. Hassan gives Rosa £5 less change than due.", who:"adult", level:1,
  jackal:"Are you trying to cheat me?",
  giraffe:{ o:"I gave you £20 for an £8 purchase and got £7 back.", f:"I feel a bit unsure", n:"because I want to be sure the change is right.", r:"Could you check the change again?" },
  say:"I think I gave you a twenty for eight pounds and got seven back — could you double-check the change?",
  empathy:"Was it an honest mistake on a busy day?",
  tip:"Assume error, not malice, with routine mistakes." }
]},
{ id:"self", name:"Self-Talk & Inner Critic", icon:"🪞", hue:300, blurb:"Turn the harsh inner voice into self-empathy: notice what happened, feel it, name the need and ask yourself for one kind next step.", cases:[
{ id:"self-01", title:"Forgot friend’s birthday", context:"Nkechi realises at midnight she forgot her best friend Tola’s birthday.", who:"self", level:1,
  jackal:"I’m such a terrible friend. No wonder people drift away from me.",
  giraffe:{ o:"I didn’t message Tola on her birthday today.", f:"I feel sad and embarrassed", n:"because I value our friendship and want her to feel loved.", r:"Will I send her a heartfelt message first thing tomorrow and suggest a belated lunch?" },
  say:"Oof, I missed Tola’s birthday. I’m sad because she matters so much to me. Tomorrow morning I’ll send her a real message and offer to take her for lunch.",
  empathy:"Could Tola be more forgiving than I expect, valuing the friendship over one date?",
  tip:"Guilt points to what you value. Use it to act, not to punish yourself." },
{ id:"self-02", title:"Mistake at work", context:"Arvind sent a report with a calculation error to his whole department.", who:"self", level:2,
  jackal:"Idiot. Everyone thinks I’m incompetent now.",
  giraffe:{ o:"The report I sent had an error in the totals.", f:"I feel embarrassed and anxious", n:"because I value competence and trust from my team.", r:"Will I send a brief correction now and add a double-check step to my process?" },
  say:"I made an error in the totals. I feel embarrassed — I really care about doing good work. I’ll send a short correction now and add a check step from now on.",
  empathy:"Might colleagues barely notice and appreciate my honesty?",
  tip:"Mistakes plus a quick fix often build more trust than perfection." },
{ id:"self-03", title:"Body image in mirror", context:"Getting dressed, Clara catches her reflection and starts criticising her stomach.", who:"self", level:2,
  jackal:"Disgusting. You let yourself go.",
  giraffe:{ o:"I’m looking at my stomach in the mirror.", f:"I feel sad and tense", n:"because I want to feel comfortable and accepted in my body.", r:"Will I put on something comfortable and name one thing my body did for me today?" },
  say:"I’m looking at my stomach and feeling tense. I really want to feel at home in my body. I’ll wear something comfy and remember this body carried me through a long week.",
  empathy:"Could my body be asking for care, not criticism?",
  tip:"Talk to yourself as you’d talk to a friend standing in front of that mirror." },
{ id:"self-04", title:"Procrastinating on essay", context:"University student Liam has opened social media 20 times instead of writing his essay due tomorrow.", who:"self", level:2,
  jackal:"Lazy, useless. You always do this.",
  giraffe:{ o:"I’ve checked my phone many times and written one paragraph.", f:"I feel anxious and overwhelmed", n:"because I need clarity and confidence about the essay.", r:"Will I put my phone in another room and write for 25 minutes on just the introduction?" },
  say:"I’ve written one paragraph and keep grabbing my phone. I think I’m overwhelmed and unsure where to start. Phone in the other room, 25 minutes, just the intro.",
  empathy:"Is my avoidance protecting me from fear of not being good enough?",
  tip:"Procrastination is often about feelings, not time. Shrink the task until it feels doable." },
{ id:"self-05", title:"Comparing to sibling", context:"At a family dinner, Andrea hears her sister’s promotion praised and feels small.", who:"self", level:2,
  jackal:"She’s the successful one. I’m the disappointment.",
  giraffe:{ o:"Everyone was praising my sister’s promotion.", f:"I feel envious and a bit lonely", n:"because I want my own efforts to be seen and valued.", r:"Will I tell my partner tonight about one thing I’m proud of this month?" },
  say:"Hearing all that praise, I felt small. I want my own path to count too. Tonight I’ll tell my partner about one thing I’m proud of.",
  empathy:"Could my family value me for different things?",
  tip:"Comparison measures your behind-the-scenes against someone else’s highlight reel." },
{ id:"self-06", title:"Yelled at kids", context:"After a long day, Femi shouted at his kids for leaving toys out.", who:"self", level:2,
  jackal:"I’m a terrible dad. I’m damaging them.",
  giraffe:{ o:"I shouted at the kids about the toys.", f:"I feel regretful and tired", n:"because I want to be a calm, loving parent, and I need rest.", r:"Will I apologise to them now and plan a 10-minute break for myself after work tomorrow?" },
  say:"I shouted at them, and I feel awful — I want to be calm and loving, and I was exhausted. I’ll go apologise now and build in a ten-minute break after work tomorrow.",
  empathy:"Do my kids need my repair more than my perfection?",
  tip:"Rupture and repair teaches children that relationships survive mistakes." },
{ id:"self-07", title:"Burnout at work", context:"Nurse Akosua wakes dreading her shift for the third week running and snaps at her partner.", who:"self", level:3,
  jackal:"Pull yourself together. Others have it worse.",
  giraffe:{ o:"For three weeks I’ve woken up dreading my shift.", f:"I feel drained and hopeless", n:"because I need rest, support and meaning in my work.", r:"Will I book a GP appointment this week and talk to my manager about my workload?" },
  say:"For three weeks I’ve dreaded every shift. I’m drained. I need rest and support, not more pushing. I’ll book a GP appointment this week and talk to my manager.",
  empathy:"Is my body telling me something important?",
  tip:"Burnout is a signal of unmet needs, not weakness — and others ‘having it worse’ doesn’t shrink yours." },
{ id:"self-08", title:"Rejected after interview", context:"Diego receives a rejection email for a job he really wanted.", who:"self", level:2,
  jackal:"Of course. I’ll never be good enough for anything.",
  giraffe:{ o:"I received a rejection email for the role.", f:"I feel disappointed and discouraged", n:"because I want growth and recognition.", r:"Will I ask for feedback and take a walk this evening to process?" },
  say:"I didn’t get the job. I’m really disappointed — I wanted that growth. I’ll ask them for feedback and go for a walk tonight.",
  empathy:"Could this rejection be about fit, not my worth?",
  tip:"Separate the outcome from your identity: ‘I didn’t get it’ not ‘I’m not good enough.’" },
{ id:"self-09", title:"Social anxiety replay", context:"After a party, Seo-jin lies awake replaying an awkward joke she made.", who:"self", level:2,
  jackal:"Everyone thinks I’m weird. Why did I say that?",
  giraffe:{ o:"I’m replaying the joke I made at the party.", f:"I feel embarrassed and anxious", n:"because I want acceptance and connection.", r:"Will I write down three moments I enjoyed tonight and then breathe slowly for two minutes?" },
  say:"I’m replaying that joke and cringing. I just want to belong. Let me jot down three good moments from tonight and breathe slowly for a couple of minutes.",
  empathy:"Could others have forgotten it already?",
  tip:"Our brains overweight awkward moments; balance them by deliberately recalling good ones." },
{ id:"self-10", title:"Broke diet goal", context:"Hassan ate a whole box of biscuits after promising himself he’d eat healthier.", who:"self", level:1,
  jackal:"No willpower. Pathetic.",
  giraffe:{ o:"I ate a box of biscuits this evening.", f:"I feel disappointed and a bit tired", n:"because I value my health, and I was hungry and stressed.", r:"Will I make a proper dinner plan for tomorrow and keep fruit handy?" },
  say:"I ate the whole box. I’m disappointed — and honestly, I was hungry and stressed. Tomorrow I’ll plan a proper dinner and keep fruit nearby.",
  empathy:"Was I meeting a need for comfort?",
  tip:"Ask what need the behaviour met — then find another way to meet it." },
{ id:"self-11", title:"Parenting guilt at work", context:"Working mum Ritu misses her son’s school play due to a work deadline.", who:"self", level:2,
  jackal:"Bad mother. He’ll remember this forever.",
  giraffe:{ o:"I missed Aarav’s school play today.", f:"I feel sad and guilty", n:"because I value being present for him and also providing for our family.", r:"Will I ask him to show me his part tonight and put the next event in my calendar now?" },
  say:"I missed his play and I’m so sad — being there matters to me, and so does providing for us. Tonight I’ll ask him to perform it for me and block the next event in my calendar.",
  empathy:"Could my son feel loved by my interest tonight?",
  tip:"Holding two values at once (presence and provision) isn’t failure — it’s a tension to navigate." },
{ id:"self-12", title:"Can’t say no", context:"Zoe agreed to cover another colleague’s shift again, despite planning a rest day.", who:"self", level:2,
  jackal:"Pushover. Why can’t you just say no?",
  giraffe:{ o:"I agreed to cover the shift on my rest day.", f:"I feel resentful and tired", n:"because I need rest and to honour my own needs.", r:"Will I practise saying ‘Let me check and get back to you’ next time?" },
  say:"I said yes to covering again and now I’m resentful. I need rest too. Next time I’ll say ‘let me check and get back to you’ instead of yes on the spot.",
  empathy:"Was I wanting to be helpful and liked?",
  tip:"Every yes to others can be a no to yourself; a pause phrase buys you time." },
{ id:"self-13", title:"Chronic illness frustration", context:"Lena, who has fibromyalgia, cancels plans again and calls herself a flake.", who:"self", level:2,
  jackal:"I’m useless. Everyone must be sick of me.",
  giraffe:{ o:"I cancelled dinner tonight because I’m in pain.", f:"I feel sad and frustrated", n:"because I want connection and to be reliable.", r:"Will I text my friend honestly and suggest a cosy video call instead?" },
  say:"I had to cancel because of pain. I’m sad — I want to see them and be reliable. I’ll text honestly and suggest a video call from the sofa.",
  empathy:"Could my friends care more about me than the plan?",
  tip:"Chronic illness isn’t a character flaw; offer adapted ways to connect." },
{ id:"self-14", title:"Missed workout streak", context:"After 30 days of running, Tariq skips a day and wants to quit entirely.", who:"self", level:1,
  jackal:"Streak’s broken. Why even bother.",
  giraffe:{ o:"I didn’t run today after 30 days in a row.", f:"I feel disappointed", n:"because I value consistency and health.", r:"Will I run tomorrow morning for just 10 minutes?" },
  say:"I missed today after thirty days. I’m disappointed — I care about this. Tomorrow, just ten minutes.",
  empathy:"Could rest also support my health?",
  tip:"Never miss twice: one off day is part of a habit, not the end of it." },
{ id:"self-15", title:"Divorce shame", context:"Recently divorced Marco feels like a failure at a wedding he attends.", who:"self", level:3,
  jackal:"Everyone’s judging me. I failed at the most important thing.",
  giraffe:{ o:"I’m at a wedding, a few months after my divorce.", f:"I feel sad and lonely", n:"because I long for love and belonging.", r:"Will I step outside for five minutes, then go and talk with my cousin?" },
  say:"Being at a wedding after the divorce is hard. I feel sad and lonely — I want love too. I’ll step out for five minutes, then go find my cousin.",
  empathy:"Could others be more compassionate than I fear?",
  tip:"Grief can visit at celebrations; let it be there without making it a verdict on you." },
{ id:"self-16", title:"Exam fail", context:"Ngozi fails her driving test for the second time.", who:"self", level:1,
  jackal:"I’m hopeless. I’ll never pass.",
  giraffe:{ o:"I didn’t pass my driving test today.", f:"I feel disappointed and nervous", n:"because I want independence and confidence.", r:"Will I ask my instructor which two things to work on and book two lessons?" },
  say:"Didn’t pass again — I’m really disappointed. I want my independence. I’ll ask my instructor for the two things to work on and book a couple of lessons.",
  empathy:"Could nerves have played a big part?",
  tip:"Swap ‘I’ll never’ for ‘I haven’t yet’." },
{ id:"self-17", title:"Inner critic as perfectionist", context:"Designer Ji-ho can’t send work to a client because ‘it’s not perfect yet’.", who:"self", level:2,
  jackal:"If it’s not flawless, they’ll see you’re a fraud.",
  giraffe:{ o:"I’ve reworked the design for three days past my own deadline.", f:"I feel anxious", n:"because I want to do excellent work and be trusted.", r:"Will I send it today with a note inviting their feedback?" },
  say:"I’ve been tweaking this for three days past my deadline. I’m anxious because I care about quality. I’ll send it today and invite their feedback.",
  empathy:"Could ‘good enough’ plus feedback lead to better work?",
  tip:"Perfectionism often protects against shame; done and improvable beats perfect and late." },
{ id:"self-18", title:"Grief and guilt", context:"Months after her father’s death, Leyla blames herself for not visiting more.", who:"self", level:3,
  jackal:"I should have been there. I’ll never forgive myself.",
  giraffe:{ o:"I’m thinking about the visits I didn’t make before Dad died.", f:"I feel grief and regret", n:"because I loved him and wanted more time together.", r:"Will I write him a letter tonight saying what I wish I’d said?" },
  say:"I keep thinking about the visits I missed. I feel such grief — I loved him and wanted more time. Tonight I’ll write him a letter with everything I wish I’d said.",
  empathy:"Would Dad want me to carry this guilt?",
  tip:"Regret is love looking backwards; consider grief support if it stays heavy." },
{ id:"self-19", title:"Money mistakes", context:"Pavel realises he’s overdrawn after impulse shopping.", who:"self", level:2,
  jackal:"You’re hopeless with money. Grow up.",
  giraffe:{ o:"My account is overdrawn by £120 after this week’s purchases.", f:"I feel worried and embarrassed", n:"because I need security and to trust myself.", r:"Will I set a weekly spending alert on my banking app tonight?" },
  say:"I’m £120 overdrawn and worried. I want to feel secure. Tonight I’ll set a weekly spending alert in my app.",
  empathy:"Was I seeking comfort or excitement with those purchases?",
  tip:"Make the next step mechanical (alerts, limits) rather than relying on willpower." },
{ id:"self-20", title:"Imposter syndrome promotion", context:"Newly promoted manager Amani feels she doesn’t deserve the role.", who:"self", level:2,
  jackal:"They’ll find out I’m a fraud.",
  giraffe:{ o:"I was promoted to team lead last week.", f:"I feel nervous and unsure", n:"because I want competence and to support my team well.", r:"Will I ask my manager for a monthly check-in for the first three months?" },
  say:"I got promoted and I feel nervous — I want to do this well. I’ll ask my manager for monthly check-ins for the first three months.",
  empathy:"Did they choose me because they see strengths I overlook?",
  tip:"Feeling unsure in a new role is normal; it means you care about doing it well." },
{ id:"self-21", title:"Late again", context:"Carlos arrives late to his weekly team meeting for the third time this month.", who:"self", level:1,
  jackal:"Unreliable. Always disappointing people.",
  giraffe:{ o:"I arrived ten minutes late to the meeting today.", f:"I feel embarrassed", n:"because I value reliability and respect for my team.", r:"Will I set a reminder 15 minutes before next week’s meeting?" },
  say:"Late again — I’m embarrassed because I value being reliable. I’ll set a fifteen-minute reminder for next week.",
  empathy:"Is my schedule too packed to transition between tasks?",
  tip:"Look at the system (calendar, buffer time) before blaming your character." },
{ id:"self-22", title:"Lonely in new city", context:"Months after moving abroad, Aiyana spends another weekend alone and calls herself unlikeable.", who:"self", level:3,
  jackal:"Nobody wants to be friends with you.",
  giraffe:{ o:"I spent this weekend alone again.", f:"I feel lonely and discouraged", n:"because I need friendship and belonging.", r:"Will I sign up for one club or class this week?" },
  say:"Another weekend alone — I feel lonely and discouraged. I need friends here. This week I’ll sign up for one club or class.",
  empathy:"Could making friends in a new place just take time?",
  tip:"Loneliness is a need signal, not a verdict; small repeated contact builds friendships." }
]}
);
